# Writes the hedra command files (and the floor textures) of Deep Delve's dungeon pieces, monsters,
# items and effects. Run from models/env: /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra); the GLBs come out Y up facing +Z (the renderer's yaw 0). Colours are exact
# Gamma Boy steps. Every piece is one game bone in scene.bake.json (art/assets.md has the budget).
import math
import os
import random

from PIL import Image

HEX = {
    # Gamma Boy (Vsigos), by value: K S G T P O N E B W Y L H A C X (dark to light)
    "K": "192119", "S": "252a2d", "G": "253825", "T": "324b41", "P": "4e4b5a", "O": "476a2f",
    "N": "6d7270", "E": "69835d", "B": "8c7661", "W": "8c8980", "Y": "84967b", "L": "82a641",
    "H": "a39b6c", "A": "a3ad8b", "C": "b3c392", "X": "b5db66",
}


def rgb(n):
    h = HEX[n]
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def col(n):
    r, g, b = (c / 255 for c in rgb(n))
    return f"--base-color {r:.4f} {g:.4f} {b:.4f}"


def mat(name, c):
    return f"material new {name} {col(c)} --no-slot"


def box(name, x, y, z, sx, sy, sz, m=None):
    out = [f"add mesh cube --name {name} --size 1 --location {x:.3f} {y:.3f} {z:.3f}",
           f"scale {sx:.3f} {sy:.3f} {sz:.3f}", "apply --scale"]
    if m:
        out.append(f"material assign {m}")
    return out


def write(name, lines):
    with open(f"{name}.txt", "w") as f:
        f.write("\n".join(lines) + "\n")


os.makedirs("textures", exist_ok=True)

# ---------------------------------------------------------------- rooms
# Six floating stone platforms, one per size (tiles of 1 m). The game turns them by 0 or 90 degrees, so
# every side has its wall. The top: flagstones, one per tile (two greys, now and then a mossy or a
# cracked one) with dark grout on each tile's west and north edges; walls 0.46 m deep; under them a
# tapering rock root (the platforms float over the abyss). Origin: the top's centre.
ROOMS = [(7, 5), (6, 5), (5, 5), (6, 4), (4, 4), (5, 3)]
PX = 6  # texels per tile (0.167 m, about two splats)
FLAG = ("T", "P")   # the two flagstones: dark teal (deep) and purple-grey (stone)
GROUT = "S"         # grout and cracks: slate (stone)
MOSS = ("O", "E")   # moss patches: olive with sage (moss)
RIM = "W"           # a pale kerb, one texel, round the platform's edge: the ledge catches the light
for k, (w, h) in enumerate(ROOMS):
    rnd = random.Random(100 + k)
    im = Image.new("RGB", (w * PX, h * PX))
    for ty in range(h):
        for tx in range(w):
            base = FLAG[0] if (tx + ty) % 2 == 0 else FLAG[1]
            if rnd.random() < 0.18:
                base = FLAG[1] if base == FLAG[0] else FLAG[0]
            base = FLAG[1] if rnd.random() < 0.3 else FLAG[0]   # mostly teal, a third purple-grey, no checker
            moss = rnd.random() < 0.1
            crack = (not moss) and rnd.random() < 0.12
            for y in range(PX):
                for x in range(PX):
                    c = base
                    if (tx == 0 and x == 0) or (ty == 0 and y == 0) or (tx == w - 1 and x == PX - 1) or (ty == h - 1 and y == PX - 1):
                        c = RIM
                    elif x == 0 or y == 0:
                        c = GROUT
                    elif moss and 1 <= x <= 3 and 2 <= y <= 4 and not (x == 3 and y == 2):
                        c = MOSS[0] if (x + y) % 3 else MOSS[1]
                    elif crack and (x == y or x == y + 1) and 2 <= x <= 5:
                        c = GROUT
                    im.putpixel((tx * PX + x, ty * PX + y), rgb(c))
    im.save(f"textures/floor_{w}x{h}.png")
    rw, rh = w * 0.62, h * 0.62
    write(f"room{w}x{h}", [
        f"# Room platform {w} x {h} tiles: a flagstone top (textures/floor_{w}x{h}.png), stone walls 0.46 m deep",
        "# with a darker footing band, and a tapering rock root beneath. Origin: the top's centre. Generated by make_env.py.",
        "new",
        "material new Floor --base-color 1 1 1 --no-slot",
        mat("Wall", "S"), mat("Footing", "K"), mat("Root", "S"),
        f"add mesh plane --name Top --size 1 --location 0 0 0",
        f"scale {w} {h} 1", "apply --scale",
        "material assign Floor", "active Top", "mode edit", "select all",
        "uv project-from-view top --scale-to-bounds", "mode object",
        "material texture Floor base-color " + f"textures/floor_{w}x{h}.png",
        # walls start 0.05 m under the top: a bridge passing under the floor never shows through them
        *box("Wall", 0, 0, -0.2, w, h, 0.3, "Wall"),
        "active Wall", "mode edit", 'select face where "normal.z > 0.9 || normal.z < -0.9"', "delete only-faces", "mode object",
        *box("Footing", 0, 0, -0.43, w - 0.06, h - 0.06, 0.16, "Footing"),
        "active Footing", "mode edit", 'select face where "normal.z > 0.9 || normal.z < -0.9"', "delete only-faces", "mode object",
        f"add mesh cone --name Root --vertices 8 --radius1 0.5 --radius2 1 --depth 1.0 --location 0 0 -1.0",
        f"scale {rw:.3f} {rh:.3f} 1", "apply --scale",
        "set rotation 0 0 22.5", "apply --rotation",
        "material assign Root",
        "active Root", "mode edit", 'select face where "normal.z > 0.9"', "delete only-faces",
        "randomize --amount 0.06 --seed " + str(7 + k), "mode object",
        "select all", "shade flat",
        f"export room{w}x{h}.glb",
    ])

# ---------------------------------------------------------------- bridge
# A plank bridge 8 m long (along x) and 0.9 m wide: 16 planks of two woods, low dark rails along both
# edges. Origin: the deck's top centre. The game lays it 0.15 m below the room floors and slides its
# spare length under the platforms it joins (they hide it), so the planks stay one per half tile.
lines = ["# Bridge: 16 planks (two woods) 8 m along x, 0.9 m wide, 0.08 m thick; rails 0.1 m square along both",
         "# edges. Origin: the deck's top centre. Generated by make_env.py.",
         "new", mat("PlankA", "B"), mat("PlankB", "P"), mat("Rail", "S")]
for i in range(16):
    x = -4 + 0.25 + i * 0.5
    lines += box(f"P{i}", x, 0, -0.04, 0.47, 0.9 if i % 3 else 0.84, 0.08, "PlankA" if i % 2 == 0 else "PlankB")
lines += box("RailN", 0, 0.46, 0.05, 8, 0.1, 0.1, "Rail")
lines += box("RailS", 0, -0.46, 0.05, 8, 0.1, 0.1, "Rail")
lines += ["select " + " ".join(f"P{i}" for i in range(16)) + " RailN RailS", "active P0", "join",
          "mode edit", 'select face where "normal.z < -0.9"', "delete only-faces", "mode object",
          "shade flat", "export bridge.glb"]
write("bridge", lines)

