# ---------------------------------------------------------------- brazier
# halo.png: the brazier's pool of light on the floor: sparse motes, 24 x 24 texels over 2.8 m (one mote a
# texel, every third texel on a staggered grid, so splats never merge them), sage near the bowl, olive
# further out, thinning with distance to nothing at r 1.4 m. The brazier stands one tile in from a
# platform's corner, so the pool always lies on floor; the flame's stepped turn makes the motes twinkle.
NH = 24
halo = Image.new("RGBA", (NH, NH))
for yy in range(NH):
    for xx in range(NH):
        d = math.hypot((xx + 0.5) / NH - 0.5, (yy + 0.5) / NH - 0.5) * 2
        grid = yy % 3 == 0 and (xx + (yy // 3) % 2 * 1 + yy // 3) % 3 == 0
        on = grid and d < 0.95 and (d < 0.55 or (xx * 7 + yy * 13) % 5 < 5 * (0.95 - d) / 0.4)
        halo.putpixel((xx, yy), rgb("E" if d < 0.55 else "O") + ((255,) if on else (0,)))
halo.save("textures/halo.png")
write("brazier", [
    "# Brazier: an iron bowl on a stone pedestal, 0.56 m across, a lime flame (an unlit cone round a bright",
    "# tongue that rises out of it) and its stippled pool of light on the floor (textures/halo.png, alpha-",
    "# masked, unlit); blocks its tile. Origin: on the floor. Generated by make_env.py.",
    "new", mat("Base", "P"), mat("Iron", "S"), mat("Flame", "L"), mat("Core", "X"),
    "material new Pool --base-color 1 1 1 --no-slot", "material texture Pool base-color textures/halo.png",
    "material set Pool alpha-mode mask", "material set Pool alpha-cutoff 0.5",
    "add mesh cone --name Base --vertices 8 --radius1 0.26 --radius2 0.16 --depth 0.5 --location 0 0 0.25",
    "material assign Base",
    "add mesh cone --name Bowl --vertices 8 --radius1 0.14 --radius2 0.3 --depth 0.2 --location 0 0 0.6",
    "material assign Iron",
    "add mesh cone --name F0 --vertices 6 --radius1 0.24 --radius2 0.1 --depth 0.26 --location 0 0 0.8",
    "material assign Flame",
    "add mesh cone --name F1 --vertices 5 --radius1 0.13 --radius2 0.02 --depth 0.42 --location 0.02 -0.03 1.0",
    "material assign Core",
    "add mesh circle --name Pool --vertices 16 --radius 1.4 --cap-fill ngon --location 0 0 0.025",
    "material assign Pool",
    "active Pool", "mode edit", "select all", "uv project-from-view top --scale-to-bounds", "mode object",
    "select all", "shade flat", "export brazier.glb",
])

